// =============================================================================
// 🧰 Helpers: Parse and Format icon string (e.g., "youtube" or "youtube::#FF0000")
// =============================================================================

export function parseIcon(value?: string | null): { id: string; color?: string } {
  if (!value) return { id: "link" };
  if (value.includes("::")) {
    const [rawId, rawColor] = value.split("::");
    const id = rawId?.trim() || "link";
    const color = rawColor?.trim() && /^#(?:[0-9a-fA-F]{3}){1,2}$/.test(rawColor.trim()) ? rawColor.trim() : undefined;
    return { id, color };
  }
  return { id: value.trim() || "link" };
}

export function formatIcon(id: string, color?: string | null): string {
  const cleanId = id.trim() || "link";
  if (color && /^#(?:[0-9a-fA-F]{3}){1,2}$/.test(color.trim())) {
    return `${cleanId}::${color.trim()}`;
  }
  return cleanId;
}

